class Solution {
    public int maxPoints(int[][] points) {
        int n = points.length, max = 1;
        for (int i = 0; i < n; i++) {
            java.util.Map<String, Integer> map = new java.util.HashMap<>();
            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                int g = gcd(Math.abs(dx), Math.abs(dy));
                if (g != 0) { dx /= g; dy /= g; }
                if (dx < 0) { dx = -dx; dy = -dy; }
                if (dx == 0) dy = Math.abs(dy);
                String key = dx + "," + dy;
                int count = map.merge(key, 2, (a, b) -> a + 1);
                max = Math.max(max, count);
            }
        }
        return max;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

class Solution {
    public int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) return n;
        int max = 2;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int count = 2;
                for (int k = j + 1; k < n; k++) {
                    int dx1 = points[j][0] - points[i][0];
                    int dy1 = points[j][1] - points[i][1];
                    int dx2 = points[k][0] - points[i][0];
                    int dy2 = points[k][1] - points[i][1];
                    if ((long) dx1 * dy2 == (long) dy1 * dx2) {
                        count++;
                    }
                }
                max = Math.max(max, count);
            }
        }
        return max;
    }
}
